function markdownToSlack(text) {
  if (!text || typeof text !== 'string') return text;

  let out = text;

  // 1. Temporarily stash code blocks to avoid mangling code syntax
  const codeBlocks = [];
  out = out.replace(/```([\s\S]*?)```/g, (match) => {
    codeBlocks.push(match);
    return `__CODE_BLOCK_${codeBlocks.length - 1}__`;
  });

  const inlineCodes = [];
  out = out.replace(/`([^`]+)`/g, (match) => {
    inlineCodes.push(match);
    return `__INLINE_CODE_${inlineCodes.length - 1}__`;
  });

  // 2. Convert standard Markdown links: [Title](URL) -> <URL|Title>
  out = out.replace(/\[([^\]\n]+)\]\(((?:https?:\/\/\vert{}mailto:)[^\s)]+)\)/g, '<$2|$1>');

  // 3. Convert Headings: # Heading -> *Heading*
  out = out.replace(/^#{1,6}\s*(.+)$/gm, '*$1*');

  // 4. Convert Bold: **text** or __text__ -> *text*
  out = out.replace(/\*\*(.*?)\*\*/g, '*$1*');
  out = out.replace(/__(.*?)__/g, '*$1*');

  // 5. Convert Strikethrough: ~~text~~ -> ~text~
  out = out.replace(/~~(.*?)~~/g, '~$1~');

  // 6. Convert Markdown horizontal rules (--- or ***) into a subtle divider line
  out = out.replace(/^(?:[-*_]\s*){3,}$/gm, '──────────');

  // 7. Clean up unordered lists for uniform Slack bullets
  out = out.replace(/^(\s*)[*+]\s+/gm, '$1• ');
  out = out.replace(/^(\s*)-\s+/gm, '$1• ');

  // 8. Collapse excessive empty lines (more than 2 down to 1 blank line)
  out = out.replace(/\n{3,}/g, '\n\n');

  // 9. Restore code blocks and inline code
  out = out.replace(/__INLINE_CODE_(\d+)__/g, (_, idx) => inlineCodes[Number(idx)]);
  out = out.replace(/__CODE_BLOCK_(\d+)__/g, (_, idx) => codeBlocks[Number(idx)]);

  return out.trim();
}

for (const item of $input.all()) {
  const agentOutput = item.json.output || item.json.text || item.json.response || '';
  item.json.slackText = markdownToSlack(agentOutput);
}

return $input.all();

