if (typeof query === "string") {
  searchTarget = query;
} else if (typeof query === "object" && query !== null) {
  searchTarget = query.query || query.input || query.searchQuery || query.q || query.some_input || query.search || query.text || query.keywords || "";
  if (!searchTarget) {
    for (const [key, val] of Object.entries(query)) {
      if (typeof val === "string" && val.trim().length > 0) {
        searchTarget = val;
        break;
      }
    }
  }
} else if (typeof input === "string") {
  searchTarget = input;
} else if (typeof input === "object" && input !== null) {
  searchTarget = input.query || input.input || input.searchQuery || input.q || input.some_input || input.search || input.text || input.keywords || "";
  if (!searchTarget) {
    for (const [key, val] of Object.entries(input)) {
      if (typeof val === "string" && val.trim().length > 0) {
        searchTarget = val;
        break;
      }
    }
  }
}

searchTarget = (searchTarget || "").trim();

if (!searchTarget) {
  return "No search query provided to SearXNG.";
}

const q = encodeURIComponent(searchTarget);

try {
  const data = await this.helpers.httpRequest({
    method: "GET",
    url: `http://searxng:8080/search?q=${q}&format=json`,
    json: true
  });

  // Updated to use Slack mrkdwn format: <url|text>
  const results = (data && data.results ? data.results : []).slice(0, 6).map((r, i) => `${i+1}. <${r.url}|${r.title}>\n${r.content}`).join("\n\n");

  return results || "No search results found for query: " + searchTarget;
} catch (err) {
  return `Error querying SearXNG: ${err.message}`;
}

